using System;
using System.Collections;
using System.Collections.Generic;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Jellyfin.Server.Helpers;

namespace Jellyfin.Tests
{
    public class StartupHelpersTests
    {
        [Fact]
        public void LogEnvironmentInfo_ShouldLogEnvironmentVariablesAndSystemInfo()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var mockAppPaths = new Mock<IApplicationPaths>();
            mockAppPaths.SetupGet(p => p.ProgramDataPath).Returns("ProgramData");
            mockAppPaths.SetupGet(p => p.LogDirectoryPath).Returns("LogDir");
            mockAppPaths.SetupGet(p => p.ConfigurationDirectoryPath).Returns("ConfigDir");
            mockAppPaths.SetupGet(p => p.CachePath).Returns("Cache");
            mockAppPaths.SetupGet(p => p.WebPath).Returns("Web");
            mockAppPaths.SetupGet(p => p.TempDirectory).Returns("Temp");
            mockAppPaths.SetupGet(p => p.ProgramSystemPath).Returns("AppPath");

            // Set environment variables
            Environment.SetEnvironmentVariable("JELLYFIN_TEST_VAR", "value");
            Environment.SetEnvironmentVariable("DOTNET_TEST_VAR2", "value2");
            Environment.SetEnvironmentVariable("UNRELATED_VAR", "should_not_appear");
            Environment.SetEnvironmentVariable("JELLYFIN_OTHER", "ignored");

            // Act
            StartupHelpers.LogEnvironmentInfo(mockLogger.Object, mockAppPaths.Object);

            // Assert
            // Verify that LogInformation was called with the expected message containing the environment variables dictionary
            mockLogger.Verify(
                logger => logger.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Environment Variables:")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);

            // Verify that the environment variables dictionary contains the relevant variables
            mockLogger.Verify(
                logger => logger.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) =>
                        v.ToString().Contains("Environment Variables:") &&
                        v.ToString().Contains("JELLYFIN_TEST_VAR") &&
                        v.ToString().Contains("DOTNET_TEST_VAR2")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }
}
